commands:
for f in phase-2-sweeps-contract phase-2-sweeps-quality phase-3-ac-gate phase-3-fix-loop; do
  echo "=== $f: bash fences with refused constructs (at PR head) ==="
  git show 6b6369e5:skills/implement/phases/$f.md 2>/dev/null | awk '
    /^[ \t]*```bash[ \t]*$/{inb=1; next}
    /^[ \t]*```[ \t]*$/{inb=0; next}
    inb && (/\$\(/ || /`/ || /\$\?/){print NR": "$0}
  ' | head -20
done
